if (!defined('CLI_SCRIPT')) { define('CLI_SCRIPT', true); }
require('/www/moodle/config.php');
require_once($CFG->dirroot . '/blocks/configurable_reports/locallib.php');
try {
    $admin = get_admin();
    \core\session\manager::set_user($admin);
    $now = time();
    $config = (object)[
        'name'          => 'Sample report \u2014 recent users',
        'summary'       => '<p>Lists the most recently created Moodle users.</p>',
        'summaryformat' => FORMAT_HTML,
        'remote'        => 0,
        'type'          => 'sql',
        'pagination'    => 0,
        'courseid'      => SITEID,
        'querysql'      => 'SELECT id, username, firstname, lastname, FROM_UNIXTIME(timecreated) AS created FROM {user} WHERE deleted = 0 ORDER BY id DESC',
        'cache'         => 0,
    ];
    $components = ['customsql' => ['config' => $config, 'sqlsyntax' => 1]];
    $reportid = $DB->insert_record('block_configurable_reports', (object)[
        'courseid'      => SITEID,
        'ownerid'       => $admin->id,
        'visible'       => 1,
        'name'          => 'Sample report \u2014 recent users',
        'summary'       => '',
        'summaryformat' => FORMAT_HTML,
        'type'          => 'sql',
        'pagination'    => 0,
        'components'    => cr_serialize($components),
        'export'        => '',
        'jsordering'    => 0,
        'global'        => 1,
        'lastexecutiontime' => 0,
        'cron'          => 0,
        'remote'        => 0,
    ]);
    echo "Inserted configurable_reports report id={$reportid}\n";
    $syscontext = context_system::instance();
    $existing = $DB->get_record('block_instances', [
        'blockname'       => 'configurable_reports',
        'parentcontextid' => $syscontext->id,
        'pagetypepattern' => 'site-index',
    ]);
    if (!$existing) {
        $blockid = $DB->insert_record('block_instances', (object)[
            'blockname'         => 'configurable_reports',
            'parentcontextid'   => $syscontext->id,
            'showinsubcontexts' => 0,
            'requiredbytheme'   => 0,
            'pagetypepattern'   => 'site-index',
            'subpagepattern'    => null,
            'defaultregion'     => 'side-pre',
            'defaultweight'     => 0,
            'configdata'        => '',
            'timecreated'       => $now,
            'timemodified'      => $now,
        ]);
        \context_block::instance($blockid);
        echo "Placed configurable_reports block on site front page (instanceid={$blockid})\n";
    } else {
        echo "Block instance already exists (id={$existing->id})\n";
    }
} catch (\Throwable $e) {
    echo 'ERROR: ' . $e->getMessage() . "\n";
}
